/**
 * radar: every Claude Code session that runs it on this machine, on a
 * braille radar in a pane opened by /radar; and the conductor, opened by
 * /radar conductor, which hands the tasks of a checklist to the sessions
 * that take them.
 *
 * Each session beats a beacon (beacon.ts) and reads the others'; the pane
 * draws them on a Raster (scope.ts) that a timer repaints in place, with the
 * list beside it. A task goes out as a brief (protocol.ts); the session
 * answers with one line, DELIVERED, BLOCKED or QUESTION, which
 * `session.receive` takes before the model sees it (conductor.tsx draws it).
 *
 * @module register
 */

import { atom, read, update } from 'claude-code'
import type { Register, RenderElement, Timer } from 'claude-code'

import type { Activity, Assignment, Received, Task } from '../types'
import { BEAT_MS, beaconDir, beaconDirs, decode, encode, fileOf, peersOf, STALE_MS } from './beacon'
import type { Beacon } from './beacon'
import { CONDUCTOR_COLOR, DRAFT_PATH, drawConductor, drawQuestion, latest, lit, sessionsOf } from './conductor'
import type { Move } from './conductor'
import { answer, brief, draft, reportOf } from './protocol'
import type { Place } from './protocol'
import { sayOf } from './say'
import type { Texts } from './say'
import { frame } from './scope'
import { blips, briefOf, closes, COLOR, elapsed, stateOf } from './sightings'
import { assignmentOf, assignmentsOf, baseOf, candidatesOf, KEPT, parseTasks, plan, resolveIn, tickTask, worktreeOf } from './tasks'

const PANE = 'radar'
/** The radar's frame and title. */
const RADAR_COLOR = '#56d364'
const WATCH_MS = 2000
const DRAFT_WAIT_MS = 10 * 60_000
const SCOPE = 'scope'
const FRAME_MS = 50
const LIST_MS = 1000
const TICK_MS = 1000
const SCAN_MS = 2000
const SPIN = '⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏'

const activity = atom({ plugin: 'radar', key: 'activity' } as const, {
  tool: null,
  isTurn: false,
  wait: null,
  since: 0,
} as Activity)
const peersAtom = atom({ plugin: 'radar', key: 'peers' } as const, [] as Beacon[])
const availableAtom = atom({ plugin: 'radar', key: 'isAvailable' } as const, false)
const taskAtom = atom({ plugin: 'radar', key: 'task' } as const, null as Received | null)
const tasksAtom = atom({ plugin: 'radar', key: 'tasks' } as const, [] as Task[])
const assignmentsAtom = atom({ plugin: 'radar', key: 'assignments' } as const, [] as Assignment[])
const fileAtom = atom({ plugin: 'radar', key: 'file' } as const, '')
const chosenAtom = atom({ plugin: 'radar', key: 'chosen' } as const, '')
const autoAtom = atom({ plugin: 'radar', key: 'isAuto' } as const, false)

/** The store keys of one repository's tasks file and of what the conductor gave out there. */
const fileKey = (root: string) => `tasksFile:${root}`
const assignmentsKey = (root: string) => `assignments:${root}`

// Module variables: a reload starts them over, and `session.start` fires again.
let current: Activity = { tool: null, isTurn: false, wait: null, since: Date.now() }
let peers: Beacon[] = []
let isAvailable = false
let selfId = ''
let selfName = 'session'
let selfBranch = ''
/** Where the beacons are written and read: the own folder, then the option's. */
let dirs: string[] = []
let isDirty = true
let isBeating = false
let wroteAt = 0
let scannedAt = 0
/** The beacons read so far, by path, with the mtime they were read at. */
const cache = new Map<string, { mtimeMs: number; beacon: Beacon | undefined }>()
/** The tools running now, by call, for the one the beacon names. */
const running = new Map<string, string>()

let startSweep: (() => void) | undefined
let sweep: Timer | undefined
let beat: Timer | undefined
let mounted: { columns: number; rows: number } | undefined
let listedAt = 0
let denials = 0

// The conductor's. Made by session.start over its own `$`: the panes' buttons,
// the timer and the receive hook call them.
let root = ''
let file = ''
let fileText: string | undefined
let watch: Timer | undefined
let isPlanning = false
/** When a draft of the tasks file was last asked for; the button waits a while. */
let draftedAt = 0
let startWatch: (() => void) | undefined
let refreshNow: (() => Promise<void>) | undefined
let give: ((move: Move) => Promise<void>) | undefined
let autoStep: (() => Promise<void>) | undefined

function selfBeacon(now: number, say: Texts): Beacon {
  const { state, detail } = stateOf(current, say)

  const beacon: Beacon = { v: 1, sessionId: selfId, name: selfName, branch: selfBranch, state, detail, since: current.since, beatAt: now }

  return isAvailable ? { ...beacon, isAvailable } : beacon
}

/** Keeps the module's copy, which the timers read, and returns it for the state. */
function mark(next: Activity): Activity {
  current = next
  isDirty = true

  return next
}

/** As `mark`, for whether this session takes tasks from a conductor. */
function markAvailable(next: boolean): boolean {
  isAvailable = next
  isDirty = true

  return next
}

/** The peers' fields a redraw depends on: the beats alone change nothing drawn. */
function shapeOf(list: readonly Beacon[]): string {
  return JSON.stringify(list.map(({ beatAt: _, ...rest }) => rest))
}

function hex(color: number): string {
  return `#${color.toString(16).padStart(6, '0')}`
}

/** The radar's size for a body this wide, and whether the list fits beside it. */
function layout(bodyColumns: number): { columns: number; rows: number; isBeside: boolean } {
  if (bodyColumns >= 64) return { columns: 28, rows: 14, isBeside: true }
  const columns = Math.max(12, Math.min(24, Math.floor((bodyColumns - 2) / 2) * 2))

  return { columns, rows: columns / 2, isBeside: false }
}

function stopSweep(): void {
  sweep?.cancel()
  sweep = undefined
}

export const register: Register = (on, options) => {
  const say = sayOf(options.language)
  const tasksFile = String(options.tasksFile ?? '').trim() || 'TASKS.md'
  const isolation = String(options.isolation ?? '').trim().toLowerCase() === 'shared' ? 'shared' : 'worktree'

  on('session.start', async ($, e, next) => {
    // The sweep lives on session.start's timers; a draw of the pane starts it.
    startSweep = () => {
      sweep ??= $.clock.every(FRAME_MS, () => {
        if (!mounted) return
        const now = Date.now()
        const cells = frame(mounted.columns, mounted.rows, now, blips([selfBeacon(now, say), ...peers], now))
        void $.ui.blit({ requestId: PANE, key: SCOPE, cells }).then(result => {
          denials = result.deny ? denials + 1 : 0
          // A second of refusals: the pane is gone; its next draw starts the sweep again.
          if (denials >= 1000 / FRAME_MS) stopSweep()
        })
        if (now - listedAt >= LIST_MS) {
          listedAt = now
          $.ui.invalidate('ui.render')
        }
      })
    }

    await $.command.register({ name: 'radar', description: say.command, argumentHint: '[available | conductor]' })
    // What the beat writes, as the state holds it across a reload.
    current = await read($, activity)
    isAvailable = await read($, availableAtom)

    root = ((await $.session.repo())?.root ?? (await $.session.cwd())).replace(/\\/g, '/')
    selfName = root.split('/').filter(Boolean).pop() ?? selfName
    const git = await $.process.run(['git', 'branch', '--show-current'], { cwd: root }).catch(() => undefined)
    selfBranch = git?.exitCode === 0 ? git.stdout.trim() : ''
    selfId = await $.session.id()
    const home = (await $.env.get('HOME')) || (await $.env.get('USERPROFILE'))
    // The own folder and every other configuration's the option names: the
    // beacon is written to each, so one side's option makes both see each
    // other; a session found in several is drawn once, by its id (peersOf).
    const own = beaconDir({ configDir: await $.env.get('CLAUDE_CONFIG_DIR'), home })
    dirs = beaconDirs(own, options.extraConfigDirs, home)

    // The beacon: written on a change (at most once a tick) and every BEAT_MS;
    // the others' read every SCAN_MS, a file again only once it changed.
    beat?.cancel()
    beat = $.clock.every(TICK_MS, () => {
      if (dirs.length === 0 || isBeating) return
      isBeating = true
      void (async () => {
        const now = Date.now()
        const id = await $.session.id()
        if (id !== selfId) {
          selfId = id // a /clear goes on under a new id
          isDirty = true
        }
        if (isDirty || now - wroteAt >= BEAT_MS) {
          isDirty = false
          wroteAt = now
          const text = encode(selfBeacon(now, say))
          for (const at of dirs) await $.fs.write(`${at}/${fileOf(selfId)}`, text).catch(() => undefined)
        }
        if (now - scannedAt < SCAN_MS) return
        scannedAt = now
        const paths = new Set<string>()
        for (const at of dirs) {
          const entries = await $.fs.list(at).catch(() => [])
          for (const entry of entries) {
            if (entry.kind !== 'file' || !entry.name.endsWith('.json') || now - entry.mtimeMs >= STALE_MS) continue
            const path = `${at}/${entry.name}`
            paths.add(path)
            if (cache.get(path)?.mtimeMs === entry.mtimeMs) continue
            const text = await $.fs.read(path).catch(() => undefined)
            cache.set(path, { mtimeMs: entry.mtimeMs, beacon: typeof text === 'string' ? decode(text) : undefined })
          }
        }
        for (const path of cache.keys()) if (!paths.has(path)) cache.delete(path)
        const seen = peersOf([...cache.values()].map(one => one.beacon), selfId, now)
        if (shapeOf(seen) !== shapeOf(peers)) await update($, peersAtom, () => seen)
        peers = seen
      })()
        .catch(() => undefined)
        .finally(() => {
          isBeating = false
        })
    })

    // The conductor. What it gave out is kept per repository across sessions,
    // so a session that restarts never hands a task out twice.
    const storedFile = await $.store.get(fileKey(root))
    if (typeof storedFile === 'string' && (await read($, chosenAtom)) === '') await update($, chosenAtom, () => storedFile)
    if ((await read($, assignmentsAtom)).length === 0) {
      const kept = assignmentsOf(await $.store.get(assignmentsKey(root)))
      if (kept.length > 0) await update($, assignmentsAtom, () => kept)
    }

    // Looks for the file where it was named, else in the usual places; reads it
    // again once it changed, and drops the tasks it no longer holds.
    const refresh = async (isForced = false) => {
      let found = ''
      let body: string | undefined
      for (const one of candidatesOf(await read($, chosenAtom), tasksFile)) {
        const path = resolveIn(root, one)
        const text = await $.fs.read(path).catch(() => undefined)
        if (typeof text === 'string') {
          found = path
          body = text
          break
        }
      }
      if (!isForced && found === file && body === fileText) return
      file = found
      fileText = body
      await update($, fileAtom, () => found)
      await update($, tasksAtom, () => (body === undefined ? [] : parseTasks(body)))
    }
    refreshNow = () => refresh(true)

    // Where a task is worked on: a worktree of its own, on a branch of its own,
    // started from what it builds on (baseOf); or, `isolation: shared`, here.
    const placeOf = async (task: Task): Promise<Place | { why: string }> => {
      if (isolation !== 'worktree') return { dir: root, from: selfName }
      const { branch, path } = worktreeOf(root, task.id)
      const { base, merges } = baseOf(task, await read($, assignmentsAtom))
      if (!(await $.fs.exists(path).catch(() => false))) {
        const git = (argv: string[]) =>
          $.process.run(['git', ...argv], { cwd: root }).catch((error: unknown) => ({ exitCode: 1, stderr: String(error) }))
        const made = await git(['worktree', 'add', '-b', branch, path, ...(base ? [base] : [])])
        // The branch may be left from an earlier round: check it out as it is.
        const again = made.exitCode === 0 ? made : await git(['worktree', 'add', path, branch])
        if (again.exitCode !== 0) return { why: (made.stderr || again.stderr || 'git worktree add').trim().split(/\r?\n/).pop() ?? '' }
      }

      return { dir: path, branch, merges, from: selfName }
    }

    give = async move => {
      const place = await placeOf(move.task)
      if ('why' in place) {
        $.ui.toast(say.c.noWorktree(move.task.id, place.why))

        return
      }
      const sent = await $.session.send({ to: { sessionId: move.sessionId }, text: brief(move.task, place) })
      if (!sent.isDelivered) {
        $.ui.toast(say.c.notSent(move.task.id, move.name, sent.reason))

        return
      }
      const now = Date.now()
      const given: Assignment = { taskId: move.task.id, sessionId: move.sessionId, name: move.name, status: 'working', note: '', since: now }
      if (place.branch) given.branch = place.branch
      const list = await update($, assignmentsAtom, all => [...all, given].slice(-KEPT))
      await $.store.set(assignmentsKey(root), list)
      $.ui.toast(say.c.sentTo(move.task.id, move.name))
    }

    autoStep = async () => {
      if (isPlanning || !(await read($, autoAtom))) return
      isPlanning = true
      try {
        const moves = plan(await read($, tasksAtom), await read($, assignmentsAtom), sessionsOf(peers))
        for (const move of moves) await give?.(move)
      } finally {
        isPlanning = false
      }
    }

    startWatch = () => {
      watch ??= $.clock.every(WATCH_MS, () => {
        void refresh()
          .then(() => autoStep?.())
          .catch(() => undefined)
        $.ui.invalidate('ui.render') // the elapsed times, the spinners
      })
      void refresh()
    }
    // A reload, or a session that had the conductor open: watch again.
    if ((await read($, fileAtom)) !== '' || (await read($, chosenAtom)) !== '') startWatch()

    return next(e)
  })

  on('session.end', async ($, e, next) => {
    // A /clear goes on under a new id: the old beacon ends, the beat goes on.
    if (e.reason !== 'clear') beat?.cancel()
    // Taking tasks is this conversation's say: the next one starts without.
    else {
      await update($, availableAtom, () => markAvailable(false))
      await update($, taskAtom, () => null)
    }
    const now = Date.now()
    const last = encode({ ...selfBeacon(now, say), sessionId: e.sessionId, endedAt: now })
    for (const at of dirs) await $.fs.write(`${at}/${fileOf(e.sessionId)}`, last).catch(() => undefined)

    return next(e)
  })

  on('command.run', { command: 'radar' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    if (arg === 'available') {
      const now = await update($, availableAtom, value => markAvailable(!value))

      return { text: now ? say.nowAvailable : say.nowUnavailable }
    }
    if (arg === 'conductor') {
      startWatch?.()
      await $.ui.open({ id: PANE, title: 'Radar' })

      return { text: say.c.opened }
    }
    await $.ui.open({ id: PANE, title: 'Radar' })

    return { text: say.opened }
  })

  on('session.receive', async ($, e, next) => {
    if (e.agentId !== undefined) return next(e)

    // A session's report on a task this one gave out: taken before the model
    // sees it, so the conductor's context pays for none of it.
    const isPeer = e.origin.kind === 'peer' || e.origin.kind === 'peer-send-message'
    const report = isPeer ? reportOf(e.text) : undefined
    const id = report && ((await read($, tasksAtom)).find(t => t.id.toLowerCase() === report.taskId.toLowerCase())?.id ?? report.taskId)
    const held = id ? assignmentOf(await read($, assignmentsAtom), id) : undefined
    if (report && held && held.status !== 'delivered') {
      const list = await update($, assignmentsAtom, all =>
        [...all, { ...held, status: report.status, note: report.note, since: Date.now() }].slice(-KEPT),
      )
      await $.store.set(assignmentsKey(root), list)
      if (report.status === 'delivered' && file !== '') {
        const text = await $.fs.read(file).catch(() => undefined)
        const ticked = typeof text === 'string' ? tickTask(text, held.taskId) : undefined
        if (ticked !== undefined) await $.fs.write(file, ticked)
      }
      $.ui.toast(say.c.reported(held.taskId, held.name, say.c[report.status], report.note))
      void autoStep?.()

      return { consumed: `radar conductor: ${report.status} ${held.taskId} from ${held.name}` }
    }

    // A conductor's brief, seen on its way to the model: the band says which
    // task this session works on, and for whom. The message goes on unchanged.
    const handed = briefOf(e.text, Date.now())
    if (handed) await update($, taskAtom, () => handed)

    return next(e)
  }).catch(($, e, next) => next(e))

  // The report that closes the task, once it went out.
  on('session.send', async ($, e, next) => {
    const sent = await next(e)
    const task = await read($, taskAtom)
    if (sent.isDelivered && e.agentId === undefined && task && closes(e.text, task.id)) {
      await update($, taskAtom, () => null)
    }

    return sent
  }).catch(($, e, next) => next(e))

  // The band: the questions this session's conductor waits on you for (a toast
  // would be gone in four seconds), then, in a session that takes tasks, the
  // task it works on or the fact that it takes them.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const asked = latest(await read($, assignmentsAtom))
      .filter(a => a.status === 'question')
      .slice(0, 2)
    const task = await read($, taskAtom)
    const isOpen = await read($, availableAtom)
    if (asked.length === 0 && !task && !isOpen) return next(e)
    const ui = $.ui.resolve(e)
    const { Box, Text, Button } = ui

    return (
      <Box flexDirection="column">
        {asked.map(a => drawQuestion(ui, a, () => void $.ui.open({ id: PANE, title: 'Radar' }), say.c))}
        {task ? (
          <Text wrap="truncate">
            <Text color="#d2a8ff">⛑ </Text>
            <Text bold>{task.id}</Text> {task.title}
            <Text dimColor>
              {' '}
              · {say.handedBy(task.from)}
            </Text>
          </Text>
        ) : isOpen ? (
          <Box flexDirection="row" gap={2}>
            <Text wrap="truncate">
              <Text color="#d2a8ff">⛑ </Text>
              {say.takesTasks}
            </Text>
            <Button key="band-leave" label={say.stop} onPress={() => update($, availableAtom, value => markAvailable(!value))} />
          </Box>
        ) : null}
      </Box>
    )
  })

  on('ui.close', { id: PANE }, async ($, e, next) => {
    stopSweep()
    mounted = undefined

    return next(e)
  }).catch(($, e, next) => next(e))

  on('turn.start', async ($, e, next) => {
    await update($, activity, () => mark({ tool: null, isTurn: true, wait: null, since: Date.now() }))

    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    running.clear()
    await update($, activity, () => mark({ tool: null, isTurn: false, wait: null, since: Date.now() }))

    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    running.set(e.tool_use_id, e.tool)
    const wait = e.tool === 'AskUserQuestion' ? 'answer' : null
    await update($, activity, () => mark({ tool: e.tool, isTurn: true, wait, since: Date.now() }))
    try {
      return await next(e)
    } finally {
      running.delete(e.tool_use_id)
      const still = [...running.values()].pop() ?? null
      await update($, activity, () => mark({ tool: still, isTurn: true, wait: null, since: Date.now() }))
    }
  }).catch(($, e, next) => next(e))

  // One pane, two frames as `dash` draws them: the radar and its sessions,
  // then the conductor.
  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const ui = $.ui.resolve(e)
    const { Box, Text, Button } = ui
    const now = Date.now()
    current = await read($, activity)
    isAvailable = await read($, availableAtom)
    peers = await read($, peersAtom)
    const task = await read($, taskAtom)
    const seen = [selfBeacon(now, say), ...peers]
    // The frame takes two columns of border and two of padding.
    const size = layout(e.props.bodyColumns - 4)

    const list = (
      <Box flexDirection="column" flexShrink={1}>
        {seen.map((b, i) => (
          <Box flexDirection="column">
            <Text wrap="truncate">
              <Text color={hex(COLOR[b.state])}>●</Text> <Text bold={i === 0}>{b.name}</Text>
              {i === 0 ? <Text color={RADAR_COLOR}>{say.you}</Text> : null}
              {b.isAvailable ? <Text color={CONDUCTOR_COLOR}> ⛑</Text> : null}
              <Text dimColor> {b.branch}</Text>
            </Text>
            <Text wrap="truncate">
              {'  '}
              <Text color={hex(COLOR[b.state])}>
                {b.state === 'busy' ? SPIN[Math.floor(now / 100) % SPIN.length] : b.state === 'waiting' ? '◌' : '·'}
              </Text>
              <Text dimColor>
                {' '}
                {b.detail} · {elapsed(now - b.since)}
              </Text>
            </Text>
          </Box>
        ))}
        {peers.length === 0 ? <Text dimColor>{say.alone}</Text> : null}
      </Box>
    )

    // This session's own part in the conductor's work: whether it takes tasks,
    // and the one it was handed.
    const self = (
      <Box flexDirection="column" marginTop={1}>
        {task ? (
          <Text wrap="truncate">
            <Text color={CONDUCTOR_COLOR}>⛑ </Text>
            <Text bold>{task.id}</Text> {task.title}
            <Text dimColor> · {say.handedBy(task.from)}</Text>
          </Text>
        ) : null}
        <Box flexDirection="row" flexWrap="wrap" gap={1}>
          <Button
            key="available"
            label={isAvailable ? say.leave : say.join}
            variant={isAvailable ? 'secondary' : 'primary'}
            hover={lit('available', CONDUCTOR_COLOR)}
            onPress={() => update($, availableAtom, value => markAvailable(!value))}
          />
        </Box>
      </Box>
    )

    const isTerminal = e.surface === 'terminal'
    let scope: RenderElement | null = null
    if (isTerminal) {
      const { Raster } = $.ui.resolve(e)
      mounted = { columns: size.columns, rows: size.rows }
      denials = 0
      startSweep?.()
      scope = <Raster key={SCOPE} columns={size.columns} rows={size.rows} cells={frame(size.columns, size.rows, now, blips(seen, now))} />
    } else {
      mounted = undefined
    }

    const radar = (
      <Box flexDirection="column">
        <Box key="head:radar" flexDirection="row" gap={1}>
          <Text bold color={RADAR_COLOR}>
            {say.title}
          </Text>
          <Text dimColor>{say.sessions(seen.length)}</Text>
        </Box>
        <Box key="frame:radar" flexDirection="column" borderStyle="round" borderColor={RADAR_COLOR} paddingX={1}>
          <Box flexDirection={size.isBeside && scope ? 'row' : 'column'} gap={2}>
            {scope}
            {list}
          </Box>
          {isTerminal ? null : <Text dimColor>{say.terminalOnly}</Text>}
          {self}
        </Box>
      </Box>
    )

    const chosen = await read($, chosenAtom)

    // The file: named in the pane, kept for this repository across sessions.
    const choose = async (value: string) => {
      const path = value.trim()
      await update($, chosenAtom, () => path)
      await $.store.set(fileKey(root), path)
      startWatch?.()
      await refreshNow?.()
    }
    // Every change to who holds what is kept for the next session too.
    const change = async (fn: (all: Assignment[]) => Assignment[]) => {
      const list = await update($, assignmentsAtom, all => fn(all).slice(-KEPT))
      await $.store.set(assignmentsKey(root), list)
    }

    const conductor = drawConductor(
      ui,
      {
        now,
        root,
        option: tasksFile,
        tasks: await read($, tasksAtom),
        assignments: await read($, assignmentsAtom),
        isAuto: await read($, autoAtom),
        found: await read($, fileAtom),
        chosen,
        sessions: sessionsOf(await read($, peersAtom)),
        isDrafting: now - draftedAt < DRAFT_WAIT_MS,
      },
      {
        choose: value => void choose(value),
        draft: () => {
          draftedAt = Date.now()
          void choose(DRAFT_PATH).then(async () => {
            await $.prompt.submit({ text: draft(DRAFT_PATH) })
            $.ui.toast(say.c.drafting(DRAFT_PATH))
          })
        },
        give: move => void give?.(move),
        answer: (a, text) =>
          void (async () => {
            const sent = await $.session.send({ to: { sessionId: a.sessionId }, text: answer(a.taskId, text) })
            if (!sent.isDelivered) {
              $.ui.toast(say.c.notSent(a.taskId, a.name, sent.reason))

              return
            }
            await change(all => [...all, { ...a, status: 'working' as const, note: '', since: Date.now() }])
            $.ui.toast(say.c.answered(a.taskId, a.name))
          })(),
        requeue: taskId => void change(all => all.filter(one => one.taskId !== taskId)),
        toggleAuto: () =>
          void (async () => {
            await update($, autoAtom, value => !value)
            await autoStep?.()
          })(),
        reload: () => {
          startWatch?.()
          void refreshNow?.()
        },
      },
      say.c,
    )

    return (
      <Box flexDirection="column">
        {radar}
        {conductor}
      </Box>
    )
  })
}

