/**
 * The beacon: one small JSON file per session under
 * `<config dir>/radar/beacons/`, rewritten while the session lives, read by
 * every other session's radar.
 *
 * The plugin's file system has no delete, so a session that ends writes its
 * beacon one last time with `endedAt`, and a session that crashed is told by
 * its beat going stale.
 *
 * @module beacon
 */

import type { Beacon, State } from '../types'

export type { Beacon, State }

/** How often a live session rewrites its beacon, at the least. */
export const BEAT_MS = 5000

/** A beacon this old is a session gone without saying so. */
export const STALE_MS = 30_000

const STATES: readonly State[] = ['busy', 'waiting', 'idle']

/**
 * The folder the beacons live in: under `CLAUDE_CONFIG_DIR` when set, else
 * under `~/.claude`, so sessions of one configuration see each other.
 *
 * @returns the folder, with `/` separators, or undefined with no home to put it in
 */
export function beaconDir(env: { configDir?: string; home?: string; userProfile?: string }): string | undefined {
  const base = env.configDir || (env.home || env.userProfile ? `${env.home || env.userProfile}/.claude` : '')

  return base === '' ? undefined : `${base.replace(/\\/g, '/').replace(/\/+$/, '')}/radar/beacons`
}

/**
 * The folders the beacons are written to and read from: the session's own, then one per
 * configuration folder `extra` names (separated by `;`, `,` or a line break,
 * never `:`, which a Windows path holds), `~` standing for the home folder.
 * A folder named twice, in any case, is read once.
 *
 * @param own the session's own beacon folder (beaconDir)
 * @param extra the `extraConfigDirs` option, as typed
 * @param home the home folder `~` stands for
 */
export function beaconDirs(own: string | undefined, extra: unknown, home?: string): string[] {
  const dirs = own === undefined ? [] : [own]
  for (const one of String(extra ?? '').split(/[;,\r\n]/)) {
    const path = one.trim().replace(/^~(?=$|[\\/])/, () => home ?? '~')
    if (path === '' || path.startsWith('~')) continue
    const dir = beaconDir({ configDir: path })
    if (dir !== undefined) dirs.push(dir)
  }
  const seen = new Set<string>()

  return dirs.filter(dir => {
    const key = dir.toLowerCase()
    if (seen.has(key)) return false
    seen.add(key)

    return true
  })
}

/** The file one session's beacon is written to: its id, made safe for a name. */
export function fileOf(sessionId: string): string {
  return `${sessionId.replace(/[^A-Za-z0-9_-]/g, '_')}.json`
}

export function encode(beacon: Beacon): string {
  return JSON.stringify(beacon)
}

/** A beacon from a file's text, or undefined for anything that is not one. */
export function decode(text: string): Beacon | undefined {
  let raw: unknown
  try {
    raw = JSON.parse(text)
  } catch {
    return undefined
  }
  if (typeof raw !== 'object' || raw === null) return undefined
  const b = raw as Record<string, unknown>
  const isText = (k: string) => typeof b[k] === 'string'
  const isTime = (k: string) => typeof b[k] === 'number' && Number.isFinite(b[k])
  if (b.v !== 1 || !['sessionId', 'name', 'branch', 'detail'].every(isText)) return undefined
  if (!['since', 'beatAt'].every(isTime) || !STATES.includes(b.state as State)) return undefined
  if (b.endedAt !== undefined && !isTime('endedAt')) return undefined
  if (b.isAvailable !== undefined && typeof b.isAvailable !== 'boolean') return undefined

  return raw as Beacon
}

/** Whether the session behind a beacon still runs: not ended, and beating. */
export function isLive(beacon: Beacon, now: number): boolean {
  return beacon.endedAt === undefined && now - beacon.beatAt < STALE_MS
}

/**
 * The beacons worth showing: not this session's, the newest copy of each
 * session (one per folder it writes to), and that copy live, so a session
 * that ended in one folder is gone from all.
 */
export function peersOf(beacons: readonly (Beacon | undefined)[], selfId: string, now: number): Beacon[] {
  const byId = new Map<string, Beacon>()
  for (const b of beacons) {
    if (!b || b.sessionId === selfId) continue
    const seen = byId.get(b.sessionId)
    if (!seen || seen.beatAt < b.beatAt) byId.set(b.sessionId, b)
  }

  return [...byId.values()]
    .filter(b => isLive(b, now))
    .sort((a, b) => a.name.localeCompare(b.name) || a.sessionId.localeCompare(b.sessionId))
}

