/**
 * The conductor's drawing: its frame in the radar's pane and its band rows,
 * from plain values and the acts the register hands it. No hook, no `$`:
 * what a press does is the caller's.
 *
 * @module conductor
 */

import type { EngineInterface, RenderElement } from 'claude-code'

import type { Assignment, Status, Task } from '../types'
import type { ConductorTexts } from './say'
import { elapsed } from './sightings'
import { assignmentOf, blockersOf, candidatesOf, isBusy, plan, shownFrom } from './tasks'

export type Elements = ReturnType<EngineInterface['ui']['resolve']>

/** A session as the conductor sees it: radar's, and whether it takes tasks. */
export type Session = { sessionId: string; name: string; state: string; isAvailable: boolean }

export type Move = { task: Task; sessionId: string; name: string }

/** Where a draft of the tasks file is asked for. */
export const DRAFT_PATH = 'docs/TASKS.md'

/** The conductor's frame, its title and its buttons' hover. */
export const CONDUCTOR_COLOR = '#c084fc'

export const STATUS_COLOR: Record<Status, string> = {
  working: '#ffa657',
  question: '#d2a8ff',
  blocked: '#ff7b72',
  delivered: '#7ee787',
}

const QUEUE_COLOR = '#79c0ff'
const HUMAN_COLOR = '#f2cc60'
const SPIN = '⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏'

/** A Button's hover: lit in its own color, scoped to its key. */
export const lit = (key: string, color: string) => ({ scope: key.slice(0, 64), color })

/** The newest assignment of each task, newest first. */
export function latest(assignments: readonly Assignment[]): Assignment[] {
  const byTask = new Map<string, Assignment>()
  for (const one of assignments) byTask.set(one.taskId, one)

  return [...byTask.values()].sort((a, b) => b.since - a.since)
}

export function sessionsOf(
  peers: readonly { sessionId: string; name: string; state: string; isAvailable?: boolean }[] | undefined,
): Session[] {
  return (peers ?? []).map(({ sessionId, name, state, isAvailable }) => ({ sessionId, name, state, isAvailable: isAvailable === true }))
}

export type ConductorView = {
  now: number
  root: string
  /** The `tasksFile` option. */
  option: string
  tasks: Task[]
  assignments: Assignment[]
  isAuto: boolean
  /** The file read, absolute, or empty while none is found. */
  found: string
  /** The file named in the pane, or empty. */
  chosen: string
  sessions: Session[]
  /** A draft was asked for a moment ago: no second button. */
  isDrafting: boolean
}

export type ConductorActs = {
  choose: (path: string) => void
  draft: () => void
  give: (move: Move) => void
  answer: (assignment: Assignment, text: string) => void
  requeue: (taskId: string) => void
  toggleAuto: () => void
  reload: () => void
}

/** The conductor's title row and frame, as `dash` draws its own. */
export function drawConductor(ui: Elements, view: ConductorView, act: ConductorActs, say: ConductorTexts): RenderElement {
  const { Box, Text, Button } = ui
  const Input = 'Input' in ui ? ui.Input : undefined
  const { now, root, tasks, assignments, sessions, found, chosen } = view
  const held = latest(assignments)
  const moves = plan(tasks, assignments, sessions)
  const free = sessions.filter(s => s.isAvailable && !isBusy(s.sessionId, assignments))
  const open = tasks.filter(t => !t.isDone && !assignmentOf(assignments, t.id))
  const human = open.filter(t => t.isHuman)
  const queued = open.filter(t => !t.isHuman && blockersOf(t, tasks).length === 0)
  const waiting = open.filter(t => !t.isHuman && blockersOf(t, tasks).length > 0)
  const done = tasks.filter(t => t.isDone).length

  const head = (
    <Box key="head:conductor" flexDirection="row" gap={1} marginTop={1}>
      <Text bold color={CONDUCTOR_COLOR}>
        {say.title}
      </Text>
      <Text dimColor wrap="truncate">
        {found ? `${shownFrom(root, found)} · ${done}/${tasks.length} ✓ · ` : ''}
        {say.sessions(sessions.length)} · {view.isAuto ? say.auto : say.manual}
      </Text>
    </Box>
  )

  // The file: named here (Enter), or looked for where it usually is.
  const picker = Input ? (
    <Input
      key="tasks-file"
      label={say.fileLabel}
      value={chosen || (found ? shownFrom(root, found) : '')}
      placeholder={candidatesOf('', view.option).join(' · ')}
      onSubmit={value => act.choose(value)}
    />
  ) : null

  if (found === '') {
    return (
      <Box flexDirection="column">
        {head}
        <Box key="frame:conductor" flexDirection="column" borderStyle="round" borderColor={CONDUCTOR_COLOR} paddingX={1}>
          {picker}
          <Text dimColor>{say.noFile(candidatesOf(chosen, view.option).join(', '))}</Text>
          {view.isDrafting ? (
            <Text color={CONDUCTOR_COLOR}>{say.drafting(DRAFT_PATH)}</Text>
          ) : (
            <Box flexDirection="row">
              <Button
                key="draft"
                label={say.draft(DRAFT_PATH)}
                variant="primary"
                hover={lit('draft', CONDUCTOR_COLOR)}
                onPress={() => act.draft()}
              />
            </Box>
          )}
        </Box>
      </Box>
    )
  }

  return (
    <Box flexDirection="column">
      {head}
      <Box key="frame:conductor" flexDirection="column" borderStyle="round" borderColor={CONDUCTOR_COLOR} paddingX={1}>
        {picker}
        {held.map(a => {
          const task = tasks.find(t => t.id === a.taskId)
          const color = STATUS_COLOR[a.status]
          const mark =
            a.status === 'working'
              ? SPIN[Math.floor(now / 100) % SPIN.length]
              : a.status === 'delivered'
                ? '✓'
                : a.status === 'question'
                  ? '?'
                  : '✕'
          const row = (
            <Text wrap="truncate" dimColor={a.status === 'delivered'}>
              <Text color={color}>●</Text> <Text bold>{a.taskId}</Text> {task?.title ?? ''} <Text dimColor>→</Text> {a.name}{' '}
              <Text color={color}>
                {mark} {say[a.status]}
              </Text>
              <Text dimColor> · {elapsed(now - a.since)}</Text>
              {a.branch ? <Text color={QUEUE_COLOR}> ⎇ {a.branch}</Text> : null}
            </Text>
          )

          // A question waits on the person: its own frame, with the answer field.
          if (a.status === 'question') {
            return (
              <Box flexDirection="column" borderStyle="round" borderColor={color} paddingX={1}>
                {row}
                <Text wrap="wrap">
                  <Text color={color}>✉ </Text>
                  {a.note}
                </Text>
                {Input ? (
                  <Input
                    key={`answer-${a.taskId}`}
                    label={say.answerLabel(a.name)}
                    placeholder={say.answerPlaceholder}
                    onSubmit={value => {
                      if (value.trim() !== '') act.answer(a, value.trim())
                    }}
                  />
                ) : null}
              </Box>
            )
          }

          return (
            <Box flexDirection="column">
              {row}
              {a.note !== '' ? (
                <Text dimColor wrap="truncate">
                  {'  ✉ '}
                  {a.note}
                </Text>
              ) : null}
              {a.status === 'blocked' ? (
                <Box flexDirection="row" paddingLeft={2}>
                  <Button
                    key={`requeue-${a.taskId}`}
                    label={say.requeue(a.taskId)}
                    hover={lit(`requeue-${a.taskId}`, color)}
                    onPress={() => act.requeue(a.taskId)}
                  />
                </Box>
              ) : null}
            </Box>
          )
        })}
        {queued.length > 0 ? (
          <Text wrap="truncate">
            <Text dimColor>{say.queue}</Text> <Text color={QUEUE_COLOR}>{queued.map(t => t.id).join(' ')}</Text>
          </Text>
        ) : null}
        {waiting.map(t => (
          <Text wrap="truncate">
            <Text dimColor>{say.waitsOn(blockersOf(t, tasks).join(', '))}</Text> {t.id}
          </Text>
        ))}
        {human.length > 0 ? (
          <Text wrap="truncate">
            <Text color={HUMAN_COLOR}>{say.human}</Text> {human.map(t => t.id).join(' ')}
          </Text>
        ) : null}
        {sessions.length === 0 ? <Text dimColor>{say.noSession}</Text> : null}
        {sessions.length > 0 && !sessions.some(s => s.isAvailable) ? <Text dimColor>{say.noneAvailable}</Text> : null}
        {free.length > 0 ? (
          <Text dimColor wrap="truncate">
            {say.free} {free.map(s => `${s.name}${s.state === 'idle' ? '' : ` (${s.state})`}`).join(', ')}
          </Text>
        ) : null}
        <Box flexDirection="row" flexWrap="wrap" gap={1}>
          {moves.map(move => (
            <Button
              key={`give-${move.task.id}`}
              label={say.give(move.task.id, move.name)}
              variant="primary"
              hover={lit(`give-${move.task.id}`, CONDUCTOR_COLOR)}
              onPress={() => act.give(move)}
            />
          ))}
          <Button
            key="auto"
            label={view.isAuto ? say.pauseAuto : say.startAuto}
            hover={lit('auto', view.isAuto ? STATUS_COLOR.blocked : STATUS_COLOR.delivered)}
            onPress={() => act.toggleAuto()}
          />
          <Button key="reload" label={say.reload} hover={lit('reload', QUEUE_COLOR)} onPress={() => act.reload()} />
        </Box>
      </Box>
    </Box>
  )
}

/** One band row: a session's question, waiting on the person, with the way to the answer field. */
export function drawQuestion(ui: Elements, a: Assignment, onAnswer: () => void, say: ConductorTexts): RenderElement {
  const { Box, Text, Button } = ui

  return (
    <Box flexDirection="row" gap={2}>
      <Text wrap="truncate">
        <Text color={STATUS_COLOR.question}>⛑ </Text>
        {a.name} · {a.taskId} <Text color={STATUS_COLOR.question}>?</Text> {a.note}
      </Text>
      <Button key={`band-answer-${a.taskId}`} label={say.answerLabel(a.name)} onPress={onAnswer} />
    </Box>
  )
}

