/**
 * What goes to a session and what comes back: the brief that hands it a
 * task, and the one-line reports it answers with.
 *
 * @module protocol
 */

import type { Status, Task } from '../types'

export type Report = { status: Exclude<Status, 'working'>; taskId: string; note: string }

const WORDS: Record<string, Report['status']> = {
  DELIVERED: 'delivered',
  BLOCKED: 'blocked',
  QUESTION: 'question',
}

const REPORT = /(?:^|\n)\s*[*_`>]*\s*(DELIVERED|BLOCKED|QUESTION)\s+([A-Za-z][A-Za-z0-9]*-\d+|#\d+)\b[*_`]*\s*[:\-–—]?\s*([^\n]*)/i

/**
 * Where a task is worked on: a worktree of its own on a branch of its own,
 * or the conductor's folder, shared with every other session.
 */
export type Place = {
  dir: string
  branch?: string
  /** The branches of delivered prerequisites the worktree did not start from. */
  merges?: string[]
  from: string
}

/** The brief a session gets: the task, who hands it, where to work, and how to report. */
export function brief(task: Task, place: Place): string {
  const lines = [
    `[conductor] Task ${task.id}: ${task.title}`,
    `Handed out by ${place.from}.`,
    ...(task.details ? ['', task.details] : []),
    '',
    `Work in ${place.dir}.`,
    place.branch
      ? `That folder is a git worktree of its own, on the branch ${place.branch}: commit your work there, on that branch, and do not merge it; name the commit in your report.`
      : 'Other sessions may work in this folder at the same time: touch only the files this task needs.',
    ...(place.branch && place.merges && place.merges.length > 0
      ? [`It builds on work delivered on other branches: before you start, run git merge ${place.merges.join(' ')} there.`]
      : []),
    'When you are done, blocked, or need an answer, send ONE message back to the session that sent you this one, with SendMessage. Its first line must be exactly one of:',
    `DELIVERED ${task.id}: <what you delivered, in one line: a commit, a PR>`,
    `BLOCKED ${task.id}: <why, in one line>`,
    `QUESTION ${task.id}: <your question>`,
  ]

  return lines.join('\n')
}

/** What this session's model is asked to write when there is no tasks file yet. */
export function draft(path: string): string {
  return [
    `Write ${path} for the conductor plugin: the work that remains in this repository, split into tasks that separate Claude Code sessions can each take on alone, at the same time, without stepping on each other.`,
    '',
    'Draw them from this conversation first, then from the repository: its README and docs, TODO and FIXME comments, failing or missing tests, open items in any changelog or plan, recent commits. Leave out what is already done.',
    '',
    'The format, which the conductor parses:',
    '- one Markdown checklist line per task: `- [ ] T-1 Short title`, ids T-1, T-2… in order;',
    '- the lines indented under a task are its brief, sent as is to the session that takes it: what to do, which files, how to tell it is done;',
    '- `(after T-1, T-2)` at the end of a task line names the tasks it waits for;',
    '- a heading or a paragraph may stand between tasks; nothing else is read.',
    '',
    'Order the tasks so the ones nothing waits on come first, keep each one small enough for a single session, and write the titles and briefs in the language of this conversation. Then say in two lines what you put in the file.',
  ].join('\n')
}

/** The answer to a session's question. */
export function answer(taskId: string, text: string): string {
  return `[conductor] ANSWER ${taskId}: ${text}\nCarry on with ${taskId}, and report the same way.`
}

/** A report in a message, wherever its line stands; undefined when it holds none. */
export function reportOf(text: string): Report | undefined {
  const found = REPORT.exec(text)
  const word = found?.[1]?.toUpperCase()
  const status = word ? WORDS[word] : undefined
  if (!found || !status) return undefined

  return { status, taskId: found[2] ?? '', note: (found[3] ?? '').trim() }
}

