// The radar screen as Raster cells: braille dots for the rings, the cross and
// the sweep's fading trail, one glyph per blip. Pure: same inputs, same cells.

/** A session on the screen: `angle` in radians clockwise from north, `range` 0 (center) to 1 (rim). */
export type Blip = { angle: number; range: number; color: number }

export const SWEEP_MS = 3200

const TAU = Math.PI * 2
const DEFAULT = 0x01000000
const GRID = 0x2f6b40
const TRAIL_DIM = 0x1f4a2c
const TRAIL_LIT = 0x7ee787
const TRAIL = 1.5 // radians of fading trail behind the beam
const BEAM = 0.06 // radians of solid beam

const BLANK = 0x20
const BRAILLE = 0x2800
const BLIP = 0x2836 // ⠶ the four middle dots
const FLASH = 0x28ff // ⣿ the whole cell, just after the beam passed

// Braille dot bits by [x][y] inside a 2 × 4 cell.
const DOT = [
  [0x01, 0x02, 0x04, 0x40],
  [0x08, 0x10, 0x20, 0x80],
]

// 4 × 4 ordered dither: a dot of the trail lights when its intensity beats this.
const BAYER = [
  [0, 8, 2, 10],
  [12, 4, 14, 6],
  [3, 11, 1, 9],
  [15, 7, 13, 5],
].map(row => row.map(v => (v + 0.5) / 16))

/** The beam's angle at `now`. */
export function beamAngle(now: number): number {
  return ((now % SWEEP_MS) / SWEEP_MS) * TAU
}

/** How far the beam has gone past `angle`, 0 to 2π. */
function behind(beam: number, angle: number): number {
  return (((beam - angle) % TAU) + TAU) % TAU
}

function mix(from: number, to: number, t: number): number {
  const c = (shift: number) => {
    const a = (from >> shift) & 0xff
    const b = (to >> shift) & 0xff

    return Math.round(a + (b - a) * t) << shift
  }

  return c(16) | c(8) | c(0)
}

function dim(color: number, k: number): number {
  return mix(0, color, k)
}

/**
 * The cells of a `columns × rows` radar at `now`, as RasterProps packs them.
 * A cell is twice as tall as wide, so `columns = 2 × rows` draws a round screen.
 */
export function frame(columns: number, rows: number, now: number, blips: readonly Blip[]): string {
  const words = new Uint32Array(columns * rows * 3)
  const dotsW = columns * 2
  const dotsH = rows * 4
  const cx = dotsW / 2
  const cy = dotsH / 2
  const radius = Math.min(dotsW, dotsH) / 2 - 0.5
  const beam = beamAngle(now)

  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < columns; col++) {
      let bits = 0
      let heat = 0
      let isGrid = false

      for (let dx = 0; dx < 2; dx++) {
        for (let dy = 0; dy < 4; dy++) {
          const px = col * 2 + dx
          const py = row * 4 + dy
          const vx = px + 0.5 - cx
          const vy = py + 0.5 - cy
          const dist = Math.hypot(vx, vy)
          if (dist > radius + 0.6) continue

          const onRing = [1, 2 / 3, 1 / 3].some(k => Math.abs(dist - radius * k) < 0.55)
          const onCross = (Math.abs(vx + 0.25) < 0.5 || Math.abs(vy + 0.25) < 0.5) && (px + py) % 2 === 0
          if (onRing || onCross) {
            bits |= DOT[dx]![dy]!
            isGrid = true
          }
          if (dist > radius) continue

          const past = behind(beam, Math.atan2(vx, -vy))
          if (past < BEAM) {
            bits |= DOT[dx]![dy]!
            heat = 1
          } else if (past < TRAIL) {
            const glow = (1 - past / TRAIL) ** 1.6
            if (glow > BAYER[py % 4]![px % 4]!) {
              bits |= DOT[dx]![dy]!
              heat = Math.max(heat, glow)
            }
          }
        }
      }

      const at = (row * columns + col) * 3
      words[at] = bits === 0 ? BLANK : BRAILLE + bits
      words[at + 1] = heat > 0 ? mix(TRAIL_DIM, TRAIL_LIT, heat) : isGrid ? GRID : DEFAULT
      words[at + 2] = DEFAULT
    }
  }

  for (const blip of blips) {
    const px = cx + Math.sin(blip.angle) * blip.range * radius
    const py = cy - Math.cos(blip.angle) * blip.range * radius
    const col = Math.min(columns - 1, Math.max(0, Math.floor(px / 2)))
    const row = Math.min(rows - 1, Math.max(0, Math.floor(py / 4)))
    const past = behind(beam, blip.angle)
    const at = (row * columns + col) * 3
    words[at] = past < 0.35 ? FLASH : BLIP
    words[at + 1] = dim(blip.color, 0.35 + 0.65 * Math.exp(-past / 1.4))
  }

  return toBase64(new Uint8Array(words.buffer))
}

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

function toBase64(bytes: Uint8Array): string {
  let out = ''
  for (let i = 0; i < bytes.length; i += 3) {
    const n = (bytes[i]! << 16) | ((bytes[i + 1] ?? 0) << 8) | (bytes[i + 2] ?? 0)
    out += ALPHABET.charAt((n >> 18) & 63) + ALPHABET.charAt((n >> 12) & 63)
    out += i + 1 < bytes.length ? ALPHABET.charAt((n >> 6) & 63) : '='
    out += i + 2 < bytes.length ? ALPHABET.charAt(n & 63) : '='
  }

  return out
}

