/**
 * From what a session does to where its blip sits: this session's own
 * activity read as a state, and every session's state read as a bearing and
 * a range on the screen.
 *
 * @module sightings
 */

import type { Activity } from '../types'
import type { Beacon, State } from './beacon'
import type { Blip } from './scope'
import type { Texts } from './say'

export const COLOR: Record<State, number> = {
  busy: 0xffa657,
  waiting: 0x79c0ff,
  idle: 0x7f7a6d,
}

const HOUR = 3_600_000

function hash(text: string): number {
  let h = 2166136261
  for (const ch of text) h = Math.imul(h ^ ch.charCodeAt(0), 16777619)

  return (h >>> 0) / 2 ** 32
}

/** A stable angle per repository, nudged per session so two of one repository part. */
export function bearing(name: string, sessionId: string): number {
  return hash(name) * Math.PI * 2 + (hash(sessionId) - 0.5) * 0.5
}

/** Busy near the center, waiting mid-way, idle drifting to the rim over an hour. */
export function range(beacon: Pick<Beacon, 'state' | 'since'>, now: number): number {
  if (beacon.state === 'busy') return 0.3
  if (beacon.state === 'waiting') return 0.58

  return 0.72 + 0.24 * Math.min(1, Math.max(0, now - beacon.since) / HOUR)
}

export function blips(beacons: readonly Beacon[], now: number): Blip[] {
  return beacons.map(b => ({
    angle: bearing(b.name, b.sessionId),
    range: range(b, now),
    color: COLOR[b.state],
  }))
}

/** This session's state and its words, from what its own hooks saw. */
export function stateOf(activity: Activity, say: Texts): { state: State; detail: string } {
  if (activity.wait === 'answer') return { state: 'waiting', detail: say.awaitsAnswer }
  if (activity.tool !== null) return { state: 'busy', detail: activity.tool }
  if (activity.isTurn) return { state: 'busy', detail: say.thinking }

  return { state: 'idle', detail: say.idle }
}

/** The task a conductor's brief hands over, or undefined for any other message. */
export function briefOf(text: string, now: number): { id: string; title: string; from: string; since: number } | undefined {
  const task = /\[conductor\] Task (\S+): ([^\n]*)/.exec(text)
  if (!task) return undefined
  const root = /^Work in (.+)\.$/m.exec(text)?.[1] ?? ''
  const from = /^Handed out by (.+)\.$/m.exec(text)?.[1]

  return {
    id: task[1] ?? '',
    title: (task[2] ?? '').trim(),
    from: from ?? root.split(/[\\/]/).filter(Boolean).pop() ?? '',
    since: now,
  }
}

/** Whether a message the session sends closes the task: delivered, or blocked. */
export function closes(text: string, id: string): boolean {
  const escaped = id.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

  return new RegExp(`(?:^|\\n)\\W*(?:DELIVERED|BLOCKED)\\s+${escaped}\\b`, 'i').test(text)
}

export function elapsed(ms: number): string {
  const s = Math.max(0, Math.floor(ms / 1000))
  if (s < 60) return `${s} s`
  if (s < 3600) return `${Math.floor(s / 60)} min`

  return `${Math.floor(s / 3600)} h`
}

files.hooks/tasks.ts:
/**
 * The tasks file: a Markdown checklist, read into tasks and ticked in place.
 *
 *     - [ ] T-12 Token expiry
 *       Tokens must expire after 15 min; see src/auth.ts.
 *     - [ ] T-19 Load tests (after T-12)
 *     - [x] T-14 Quota screen
 *
 * @module tasks
 */

import type { Assignment, Task } from '../types'

const ITEM = /^(\s*)[-*+]\s+\[( |x|X)\]\s+(.*)$/
const ID = /^([A-Za-z][A-Za-z0-9]*-\d+)\b[\s:.)-]*/
const AFTER = /\s*\((?:after|après|apres)\s+([^)]*)\)/i
/** The mark of a task that is the person's to do, never a session's. */
const HUMAN = /👤/u

/** Where the tasks file is looked for, in order: the one chosen, else the option's and the usual two. */
export function candidatesOf(chosen: string, option: string): string[] {
  const list = chosen.trim() !== '' ? [chosen.trim()] : [option.trim() || 'TASKS.md', 'TASKS.md', 'docs/TASKS.md']

  return [...new Set(list.map(one => one.replace(/\\/g, '/').replace(/^\.\//, '')))]
}

/** A path from the repository's root made absolute; an absolute one as it is, with `/`. */
export function resolveIn(root: string, path: string): string {
  const p = path.trim().replace(/\\/g, '/')

  return /^([A-Za-z]:)?\//.test(p) ? p : `${root.replace(/\/+$/, '')}/${p.replace(/^\.\//, '')}`
}

/**
 * Where a task is worked on when each gets its own worktree: a branch
 * `conductor/<task>` and a folder beside the repository,
 * `<parent>/<repository>.tasks/<task>`, so nothing lands inside it.
 */
export function worktreeOf(root: string, taskId: string): { branch: string; path: string } {
  const slug = taskId.toLowerCase().replace(/^#/, 'n').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'task'
  const base = root.replace(/\\/g, '/').replace(/\/+$/, '')
  const cut = base.lastIndexOf('/')
  const parent = cut < 0 ? '.' : base.slice(0, cut)
  const repo = base.slice(cut + 1) || 'repo'

  return { branch: `conductor/${slug}`, path: `${parent}/${repo}.tasks/${slug}` }
}

/**
 * What a task's worktree starts from: the branch its first prerequisite was
 * delivered on, the others' to merge in first; none, the current branch. A
 * prerequisite delivered with no branch (shared folder) is already there.
 */
export function baseOf(task: Task, assignments: readonly Assignment[]): { base?: string; merges: string[] } {
  const branches = task.after
    .map(id => assignmentOf(assignments, id))
    .filter((a): a is Assignment => a?.status === 'delivered' && typeof a.branch === 'string' && a.branch !== '')
    .map(a => a.branch as string)
  const [base, ...merges] = [...new Set(branches)]

  return base === undefined ? { merges: [] } : { base, merges }
}

/** An absolute path as the pane shows it: from the repository's root when under it. */
export function shownFrom(root: string, path: string): string {
  const base = `${root.replace(/\/+$/, '')}/`

  return path.toLowerCase().startsWith(base.toLowerCase()) ? path.slice(base.length) : path
}

export function parseTasks(text: string): Task[] {
  const lines = text.split(/\r?\n/)
  const tasks: Task[] = []
  let open: { task: Task; indent: number; details: string[] } | undefined

  const close = () => {
    if (open) open.task.details = open.details.join('\n').trim()
    open = undefined
  }

  lines.forEach((line, at) => {
    const item = ITEM.exec(line)
    if (item) {
      close()
      let rest = item[3] ?? ''
      const after: string[] = []
      rest = rest.replace(AFTER, (_, ids: string) => {
        after.push(...ids.split(/[\s,;]+/).filter(Boolean))

        return ''
      })
      const named = ID.exec(rest)
      const id = named?.[1] ?? `#${tasks.length + 1}`
      const title = (named ? rest.slice(named[0].length) : rest).trim()
      const isHuman = HUMAN.test(title)
      const task: Task = { id, title, details: '', after, isDone: item[2] !== ' ', isHuman, line: at }
      tasks.push(task)
      open = { task, indent: (item[1] ?? '').length, details: [] }

      return
    }
    if (!open) return
    const indent = /^\s*/.exec(line)?.[0].length ?? 0
    if (line.trim() === '' || indent > open.indent) open.details.push(line.trim())
    else close()
  })
  close()

  return tasks
}

/** The file with one task's box checked, or undefined when the task is not there. */
export function tickTask(text: string, id: string): string | undefined {
  const task = parseTasks(text).find(one => one.id === id)
  if (!task) return undefined
  const eol = text.includes('\r\n') ? '\r\n' : '\n'
  const lines = text.split(/\r?\n/)
  lines[task.line] = (lines[task.line] ?? '').replace(/\[ \]/, '[x]')

  return lines.join(eol)
}

/** The assignment a task has now: the newest one, delivered or not. */
export function assignmentOf(assignments: readonly Assignment[], id: string): Assignment | undefined {
  return assignments.filter(one => one.taskId === id).pop()
}

/**
 * Whether a task can be given out: open, the person's to do (👤) never, never
 * given (a blocked one waits for the person to put it back in the queue), its
 * prerequisites done.
 */
export function isReady(task: Task, tasks: readonly Task[], assignments: readonly Assignment[]): boolean {
  if (task.isDone || task.isHuman || assignmentOf(assignments, task.id)) return false

  return blockersOf(task, tasks).length === 0
}

/** The prerequisites of a task still open; one the file does not hold blocks nothing. */
export function blockersOf(task: Task, tasks: readonly Task[]): string[] {
  return task.after.filter(id => tasks.some(one => one.id === id && !one.isDone))
}

/** How many assignments are kept for a repository, across sessions. */
export const KEPT = 200

/** The assignments a store held, the malformed left out; [] for anything else. */
export function assignmentsOf(raw: unknown): Assignment[] {
  if (!Array.isArray(raw)) return []
  const STATUSES = ['working', 'question', 'blocked', 'delivered']

  return raw
    .filter(
      (one): one is Assignment =>
        typeof one === 'object' &&
        one !== null &&
        ['taskId', 'sessionId', 'name', 'note'].every(k => typeof (one as Record<string, unknown>)[k] === 'string') &&
        typeof (one as Record<string, unknown>).since === 'number' &&
        STATUSES.includes(String((one as Record<string, unknown>).status)),
    )
    .slice(-KEPT)
}

/** Whether a session holds a task now: working on it, or waiting on an answer. */
export function isBusy(sessionId: string, assignments: readonly Assignment[]): boolean {
  const latest = new Map<string, Assignment>()
  for (const one of assignments) latest.set(one.taskId, one)

  return [...latest.values()].some(one => one.sessionId === sessionId && (one.status === 'working' || one.status === 'question'))
}

/**
 * The next moves: each free session, in order, gets the next ready task, in
 * the file's order; a session is free when it takes tasks (`/radar
 * available`), holds none and is idle.
 */
export function plan(
  tasks: readonly Task[],
  assignments: readonly Assignment[],
  sessions: readonly { sessionId: string; name: string; state: string; isAvailable?: boolean }[],
): { task: Task; sessionId: string; name: string }[] {
  const ready = tasks.filter(task => isReady(task, tasks, assignments))
  const free = sessions.filter(s => s.isAvailable === true && s.state === 'idle' && !isBusy(s.sessionId, assignments))
  const moves: { task: Task; sessionId: string; name: string }[] = []
  for (const [i, s] of free.entries()) {
    const task = ready[i]
    if (!task) break
    moves.push({ task, sessionId: s.sessionId, name: s.name })
  }

  return moves
}

