files.types/index.d.ts:
/** What a session is doing, as its radar says it. */
export type State = 'busy' | 'waiting' | 'idle'

export type Beacon = {
  v: 1
  sessionId: string
  /** The repository's folder name, or the working directory's. */
  name: string
  branch: string
  state: State
  /** The tool running, or what the session waits for. */
  detail: string
  /** When the state began, ms since the epoch. */
  since: number
  /** When the beacon was last written. */
  beatAt: number
  /** Set by the session's last write, as it ends. */
  endedAt?: number
  /** Set while the session takes tasks from a conductor (`/radar available`). */
  isAvailable?: boolean
}

/** What this session is doing, as its own hooks saw it. */
export type Activity = {
  /** The tool running now, or null. */
  tool: string | null
  /** True from `turn.start` to `turn.complete`. */
  isTurn: boolean
  /** Set while the session waits on the person to answer its question. */
  wait: 'answer' | null
  /** When the current state began, ms since the epoch. */
  since: number
}

/** A task a conductor handed this session, as its brief said it. */
export type Received = {
  id: string
  title: string
  /** The folder name of the repository the conductor runs in. */
  from: string
  since: number
}

/** One task of the tasks file: a checklist line and the lines indented under it. */
export type Task = {
  /** `T-12` as written, or `#3` (its rank) for a line that names none. */
  id: string
  title: string
  /** The indented lines under it, sent with the task. */
  details: string
  /** The ids it waits for: `(after T-12, T-13)`. */
  after: string[]
  /** Checked: `- [x]`. */
  isDone: boolean
  /** Marked 👤: the person's to do, never handed to a session. */
  isHuman: boolean
  /** Its line in the file, 0-based. */
  line: number
}

/** Where a task given to a session stands, as its reports say. */
export type Status = 'working' | 'question' | 'blocked' | 'delivered'

export type Assignment = {
  taskId: string
  /** The session it went to, and its name on the radar. */
  sessionId: string
  name: string
  status: Status
  /** The last report's text: the question, why it is blocked, what was delivered. */
  note: string
  /** When the status began, ms since the epoch. */
  since: number
  /** The branch of the task's own worktree, when it got one. */
  branch?: string
}

declare module 'claude-code' {
  interface PluginState {
    radar: {
      activity: Activity
      peers: Beacon[]
      isAvailable: boolean
      task: Received | null
      // The conductor: the tasks of the tasks file, who holds which, where the
      // file is, and whether ready tasks go out by themselves.
      tasks: Task[]
      assignments: Assignment[]
      /** The tasks file's absolute path, or empty while none is found. */
      file: string
      /** The tasks file the person named in the pane; empty, the usual places. */
      chosen: string
      isAuto: boolean
    }
  }
}
